import * as T from 'three/webgpu';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {unpackShip,disposeShip} from '../render/ship-assets.js';
import {architecturalRecipe} from './architecture.js';
import {ARCHITECTURAL_KITS} from './design.js';
import {citySurfaceNodes} from './surface-nodes.js';
import {windowNodes} from './window-nodes.js';
import {streetMaterials} from './street-materials.js';
const $=id=>document.getElementById(id),scene=new T.Scene(),camera=new T.PerspectiveCamera(42,1,.1,500),renderer=new T.WebGPURenderer({antialias:true}),sun=new T.DirectionalLight(0xfff1e5,3.8),sky=new T.HemisphereLight(0xd7e8f1,0x6e756c,.8);
let worker,building,streets,street,job=0,frame=0,dirty=true,rendering=false,pmrem,environment;
for(const [id,k]of Object.entries(ARCHITECTURAL_KITS)){const o=document.createElement('option');o.value=id;o.textContent=k.name;$('kit').append(o);} $('kit').value='aurelia';
scene.background=new T.Color(0x9aaeb8);scene.add(sun,sun.target,sky);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-32,right:32,top:32,bottom:-32,near:.1,far:120});sun.shadow.normalBias=.025;sun.shadow.bias=-.0001;
const mount=$('viewport');renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1;mount.append(renderer.domElement);camera.position.set(21,13,22);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,4,0);controls.update();controls.addEventListener('change',()=>dirty=true);
function light(){sun.position.set(...($('light').value==='raking'?[35,8,6]:[30,38,8]));dirty=true;}
function dispose(){if(building){scene.remove(building);disposeShip(building);}if(streets){scene.remove(streets);streets.traverse(m=>m.geometry?.dispose());streets.userData.paint.dispose();street.dispose();}}
function road(){streets=new T.Group();street=streetMaterials($('seed').value,Number($('wear').value),$('planet').value);
 for(const [w,d,x,z,m]of [[12,32,9,0,street.road],[3,32,1.5,0,street.stone],[3,32,16.5,0,street.stone]]){const mesh=new T.Mesh(new T.BoxGeometry(1,.18,1),m);if(m.userData.citySurface?.road)mesh.geometry.setAttribute('streetSize',new T.Float32BufferAttribute(Array.from({length:mesh.geometry.attributes.position.count},()=>[w,d]).flat(),2));mesh.scale.set(w,1,d);mesh.position.set(x,-.04,z);mesh.receiveShadow=true;streets.add(mesh);}
 const paint=new T.MeshStandardNodeMaterial({color:0xdbd9bd,roughness:.86});paint.addEventListener('dispose',()=>{});for(let z=-14;z<16;z+=6){const line=new T.Mesh(new T.BoxGeometry(.12,.008,2.6),paint);line.position.set(9,.055,z);streets.add(line);}streets.userData.paint=paint;scene.add(streets);
}
function rebuild(){
 $('status').textContent='Baking procedural finishes…';worker?.terminate();worker=new Worker(new URL('./studio-worker.js',import.meta.url),{type:'module'});const id=++job;
 const recipe=architecturalRecipe('modular',$('seed').value,0,{style:$('planet').value,design:{kit:$('kit').value,finishRoughness:Number($('roughness').value),panelVariation:Number($('variation').value),complexity:.2}});recipe.modules=[{id:'specimen',shape:'chamfer',role:'podium',width:10,height:12,depth:8,x:-7,y:0,z:0,yaw:0,taper:0,facade:true,pattern:'punched',roof:'sealed',finish:'ceramic',levels:[{y:0,scale:1,twist:0},{y:12,scale:1,twist:0}]}];
 worker.onmessage=({data})=>{if(data.id!==job)return;if(data.error){$('status').textContent=data.error;return;}dispose();building=unpackShip(data.payload);const canonical=new Map();for(const mesh of building.children){const source=mesh.material;if(!canonical.has(source.name)){const material=windowNodes(citySurfaceNodes(new T.MeshStandardNodeMaterial().copy(source)));material.transparent=false;canonical.set(source.name,material);}mesh.material=canonical.get(source.name);source.dispose();mesh.castShadow=mesh.receiveShadow=true;}for(const part of data.parts.filter(p=>p.kind==='foundation'))for(const mesh of building.children.slice(part.start,part.start+part.count))mesh.visible=false;building.visible=true;scene.add(building);road();dirty=true;$('status').textContent='Ready · shared production worker / WebGPU · 2 m surface repeat';};worker.onerror=e=>$('status').textContent=e.message;worker.postMessage({id,recipe,lod:0,wear:Number($('wear').value)});
}
$('rebuild').onclick=rebuild;for(const id of ['kit','planet','wear','roughness','variation'])$(id).onchange=rebuild;$('light').onchange=light;$('close').onclick=()=>{camera.position.set(2.8,2.2,8);controls.target.set(-1,2,3.6);controls.update();dirty=true;};$('fit').onclick=()=>{camera.position.set(21,13,22);controls.target.set(0,4,0);controls.update();dirty=true;};
new ResizeObserver(()=>{camera.aspect=mount.clientWidth/mount.clientHeight;camera.updateProjectionMatrix();renderer.setSize(mount.clientWidth,mount.clientHeight);dirty=true;}).observe(mount);
try{await renderer.init();if(!renderer.backend.isWebGPUBackend)throw Error('WebGPU is required');
 const backdrop=new T.Scene(),sphere=new T.SphereGeometry(60,32,16),colors=[];for(let i=0;i<sphere.attributes.position.count;i++){const y=sphere.attributes.position.getY(i)/60,c=new T.Color(0xc2d1d7).lerp(new T.Color(y>0?0x718fa6:0x737974),Math.min(1,Math.abs(y)*2));colors.push(c.r,c.g,c.b);}sphere.setAttribute('color',new T.Float32BufferAttribute(colors,3));const skyMaterial=new T.MeshBasicNodeMaterial({vertexColors:true,side:T.BackSide});backdrop.add(new T.Mesh(sphere,skyMaterial));pmrem=new T.PMREMGenerator(renderer);environment=pmrem.fromScene(backdrop,.03);scene.environment=environment.texture;scene.environmentIntensity=.6;sphere.dispose();skyMaterial.dispose();
 const floor=new T.Mesh(new T.PlaneGeometry(150,150),new T.MeshStandardNodeMaterial({color:0x929b99,roughness:.94}));floor.rotation.x=-Math.PI/2;floor.position.y=-.16;floor.receiveShadow=true;scene.add(floor);light();rebuild();renderer.backend.device.addEventListener('uncapturederror',e=>{document.body.dataset.gpuError=e.error.message;$('status').textContent=e.error.message;});renderer.setAnimationLoop(async()=>{if(!dirty||rendering)return;dirty=false;rendering=true;try{await renderer.renderAsync(scene,camera);await renderer.backend.device.queue.onSubmittedWorkDone();document.body.dataset.frame=String(++frame);}finally{rendering=false;}});}catch(e){$('status').textContent=e.message;}
window.addEventListener('pagehide',()=>{worker?.terminate();renderer.setAnimationLoop(null);dispose();environment?.dispose();pmrem?.dispose();controls.dispose();renderer.dispose();},{once:true});
